import './navbar.scss';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import DarkModeOutlinedIcon from '@mui/icons-material/DarkModeOutlined';
import WbSunnyOutlinedIcon from '@mui/icons-material/WbSunnyOutlined';
import GridViewOutlinedIcon from '@mui/icons-material/GridViewOutlined';
import NotificationsOutlinedIcon from '@mui/icons-material/NotificationsOutlined';
import EmailOutlinedIcon from '@mui/icons-material/EmailOutlined';
import PersonOutlinedIcon from '@mui/icons-material/PersonOutlined';
import SearchOutlinedIcon from '@mui/icons-material/SearchOutlined';
import LogoutOutlinedIcon from '@mui/icons-material/LogoutOutlined';
import { Link, useNavigate } from 'react-router-dom';
import { useContext, useEffect, useState } from 'react';
import { DarkModeContext } from '../../context/darkModeContext';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';

const Navbar = () => {
  const { toggle, darkMode } = useContext(DarkModeContext);
  const { currentUser, logout } = useContext(AuthContext);
  const navigate = useNavigate();
  const [friendRequests, setFriendRequests] = useState([]);

  useEffect(() => {
    console.log('Navbar: currentUser=', currentUser);
    console.log('Navbar: profilePicture=', currentUser?.profilePicture);

    const fetchFriendRequests = async () => {
      try {
        const token = sessionStorage.getItem('token');
        const res = await axios.get('http://localhost:5000/api/users/friend-requests/pending', {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('Navbar: Friend requests:', res.data);
        setFriendRequests(res.data);
      } catch (err) {
        console.error('Navbar: Error fetching friend requests:', err);
      }
    };

    if (currentUser) {
      fetchFriendRequests();
    }
  }, [currentUser]);

  const handleNotificationsClick = () => {
    navigate('/notifications');
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Navbar: No profile picture provided, using default');
      return '/default-avatar.png';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Navbar: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Navbar: Profile picture URL:', url);
    fetch(url)
      .then((res) => console.log('Navbar: Profile picture fetch status:', res.status, res.statusText))
      .catch((err) => console.error('Navbar: Profile picture fetch error:', err));
    return url;
  };

  return (
    <div className="navbar">
      <div className="left">
        <Link to="/" style={{ textDecoration: 'none' }}>
          <span>Yoursocial</span>
        </Link>
        <Link to="/" style={{ textDecoration: 'none' }}>
          <HomeOutlinedIcon style={{ cursor: 'pointer' }} />
        </Link>
        {darkMode ? (
          <WbSunnyOutlinedIcon onClick={toggle} style={{ cursor: 'pointer' }} />
        ) : (
          <DarkModeOutlinedIcon onClick={toggle} style={{ cursor: 'pointer' }} />
        )}
        <GridViewOutlinedIcon />
        <div className="search">
          <SearchOutlinedIcon />
          <input type="text" placeholder="Search..." />
        </div>
      </div>
      <div className="right">
        <PersonOutlinedIcon />
        <EmailOutlinedIcon />
        <div className="notifications">
          <NotificationsOutlinedIcon onClick={handleNotificationsClick} style={{ cursor: 'pointer' }} />
          {friendRequests.length > 0 && (
            <span className="badge">{friendRequests.length}</span>
          )}
        </div>
        <div className="user">
          {currentUser ? (
            <>
              <img
                src={getProfilePictureUrl(currentUser.profilePicture)}
                alt={`${currentUser.name}'s profile`}
                onError={(e) => {
                  console.error('Navbar: Profile picture load error:', e);
                  e.target.src = '/default-avatar.png';
                }}
              />
              <span>{currentUser.name}</span>
            </>
          ) : (
            <span>Loading...</span>
          )}
        </div>
        <LogoutOutlinedIcon onClick={() => {
          logout();
          navigate('/login');
        }} style={{ cursor: 'pointer' }} />
      </div>
    </div>
  );
};

export default Navbar;
